const STATE_CHECK = "State and audit log verify (MAC, signed head, key pin)";

/** Adapter checks in the order the code runs them (core/state.ts, core/access/policy.ts, core/adapter.ts). */
function adapterChecks(reply                         , reason               )          {
  if (reply.error === "integrity_failure") return [{ name: STATE_CHECK, pass: false }];
  const chain                     = [
    ["File exists", "unknown_asset"],
    ["Account not disabled", "disabled"],
    ["Identity not revoked", "revoked"],
    ["Identity owns the file", "not_owner"],
    ["Identity not quarantined", "quarantined"],
  ];
  const out          = [{ name: STATE_CHECK, pass: true }];
  for (const [name, code] of chain) {
    if (reason === code) return [...out, { name, pass: false }];
    out.push({ name, pass: true });
  }
  return out;
}

/** Cluster node checks in the order ClusterNode.authorize runs them. */
function nodeChecks(reason        )          {
  const chain                       = [
    ["Node holds a verified policy", ["no_policy"]],
    ["Device is enrolled", ["unknown_device"]],
    ["Device belongs to the user", ["device_owner_mismatch"]],
    ["Device not revoked", ["device_revoked"]],
    ["User not revoked", ["actor_revoked"]],
    ["ML-DSA request signature valid", ["bad_signature"]],
    ["Request addressed to this node", ["wrong_node"]],
    ["Timestamp within ±30 s", ["stale_or_future_request"]],
    ["Nonce never seen before", ["replayed_request"]],
    ["Key version accepted", ["unknown_key_version", "key_version_retired"]],
  ];
  const out          = [];
  for (const [name, codes] of chain) {
    if (codes.includes(reason)) return [...out, { name, pass: false }];
    out.push({ name, pass: true });
  }
  return out;
}

