// ---------- generic storyboards for the remaining attacks (sandboxed) ----------

const GENERIC_IDS = ["policy-rollback", "consistent-rollback", "edit-log", "malformed", "delete-signing-key"];

function generic(id        )                   {
  const a = listAttacks().find((x) => x.id === id);
  if (!a) return null;
                                                  
  return {
    id: a.id,
    name: a.name,
    summary: a.attack,
    impact: "Runs in an isolated sandbox instance (it needs a fresh instance or its own witness), so the monitor does not change.",
    defense: a.defense,
    live: false,
    steps: [
      { actor: "attacker", title: "The attack", caption: a.attack, run: (c) => { c.set("result", runAttack(id)[0]); return { evidence: "run against a fresh, isolated instance" }; } },
      { actor: "service", title: "The defence", caption: a.defense, run: (c) => { const r = c.get   ("result"); return { checks: [{ name: a.defense, pass: r.blocked }], tone: r.blocked ? "good" : "bad", evidence: r.evidence }; } },
      { actor: "service", title: "Outcome", caption: "The real evidence from the sandboxed run.", run: (c) => { const r = c.get   ("result"); return { tone: r.blocked ? "good" : "bad", evidence: r.blocked ? `Blocked. ${r.evidence}` : `Not blocked: ${r.evidence}` }; } },
    ],
  };
}

const attack = (id        )                   => LIVE.find((a) => a.id === id) ?? (GENERIC_IDS.includes(id) ? generic(id) : null);

export function labCatalog() {
  return [...LIVE, ...GENERIC_IDS.map(generic).filter((x)                 => x !== null)].map((a) => ({
    id: a.id,
    name: a.name,
    summary: a.summary,
    impact: a.impact,
    defense: a.defense,
    live: a.live,
    needs_cluster: a.needsCluster ?? false,
    steps: a.steps.map((s) => ({ actor: s.actor, title: s.title, caption: s.caption })),
  }));
}

// ---------- run lifecycle ----------

                                                                                                                                                                                                   
const RUN_ID = /^[0-9]+-[0-9a-f]{6}$/;

function context(run         , dir        )      {
  const paths = statePaths();
  return {
    run: dir,
    paths,
    cluster: clusterDir(),
    get:    (k        ) => run.ctx[k]     ,
    set: (k, v) => {
      run.ctx[k] = v;
    },
    call: (req) => handle(JSON.stringify(req), paths).body                           ,
  };
}

/**
 * What the Live Monitor mirrors: the latest step with its REAL outcome (evidence, checks, the signed
 * records it produced and the alerts it raised) plus the run's events, so the monitor can animate it.
 */
function save(run         , dir        , summary        ) {
  atomicWriteFile(join(dir, "run.json"), JSON.stringify(run));
  const last = run.events.at(-1);
  const base = { run_id: run.id, attack: run.attack, name: run.name, total: run.total, live: attack(run.attack)?.live ?? true, events: run.events };
  const current = last
    ? { ...base, state: run.done ? "finished" : "running", step: last.step, actor: last.actor, title: last.title, caption: last.caption, evidence: last.evidence, checks: last.checks, tone: last.tone, audit_seq: last.audit_seq, records: last.records, alerts: last.alerts, at: last.at, done: run.done }
    : { ...base, state: "ready", step: 0, actor: null, title: "Ready", caption: summary, evidence: "", checks: [], tone: "neutral", audit_seq: null, records: [], alerts: [], at: run.started_at, done: false };
  atomicWriteFile(join(labDir(), "current.json"), JSON.stringify(current));
}

/** The Lab is between attacks (another attack selected, or "Run again"): the monitor shows no stale step. */
export function labIdle() {
  mkdirSync(labDir(), { recursive: true, mode: 0o700 });
  atomicWriteFile(join(labDir(), "current.json"), JSON.stringify({ state: "idle", at: Date.now() }));
  return { idle: true };
}

/** After a demo reset, unfinished runs must not be resumed against the reset service. */
export function labAbandon() {
  let abandoned = 0;
  if (existsSync(labDir())) {
    for (const d of readdirSync(labDir())) {
      if (!RUN_ID.test(d) || !existsSync(join(labDir(), d, "run.json"))) continue;
      try {
        const run = JSON.parse(readFileSync(join(labDir(), d, "run.json"), "utf8"))           ;
        if (run.done) continue;
        run.done = true;
        run.abandoned = true;
        atomicWriteFile(join(labDir(), d, "run.json"), JSON.stringify(run));
        abandoned++;
      } catch {
        // unreadable run: ignore
      }
    }
  }
  labIdle();
  return { abandoned };
}

export function labStart(id        ) {
  const a = attack(id);
  if (!a) return { error: "unknown_attack" };
  if (a.needsCluster && !existsSync(join(clusterDir(), "demo-device.json"))) return { error: "cluster_not_started", message: "Start the cluster on the Nodes page first." };
  mkdirSync(labDir(), { recursive: true, mode: 0o700 });
  const runId = `${Date.now()}-${randomBytes(3).toString("hex")}`;
  const dir = join(labDir(), runId);
  const run          = { id: runId, attack: a.id, name: a.name, started_at: Date.now(), next: 0, total: a.steps.length, ctx: {}, events: [], done: false };
  const blocked = a.precondition?.(context(run, dir));
  if (blocked) return { error: "precondition", message: blocked };
  mkdirSync(dir, { mode: 0o700 });
  save(run, dir, a.summary);
  return { run_id: runId, attack: a.id, total: a.steps.length };
}

export function labStep(runId        ) {
  if (!RUN_ID.test(runId)) return { error: "invalid_run" };
  const dir = join(labDir(), runId);
  if (!existsSync(join(dir, "run.json"))) return { error: "unknown_run" };
  const run = JSON.parse(readFileSync(join(dir, "run.json"), "utf8"))           ;
  const a = attack(run.attack);
  if (!a || run.done) return { error: "run_finished" };
  const def = a.steps[run.next];
  const c = context(run, dir);
  const before = evidenceKeys(c);
  let r            ;
  try {
    r = def.run(c);
  } catch (err) {
    r = { tone: "bad", evidence: `step failed: ${err instanceof Error ? err.message : "error"}` };
  }
  // Read back what the step really produced from the signed logs (service + every node).
  const produced = producedSince(c, before);
  const decisionRec = produced.records.find((x) => x.service === SERVICE_NAME && x.type !== "security_alert") ?? produced.records.find((x) => x.service === SERVICE_NAME);
  const ev           = {
    step: run.next + 1,
    actor: def.actor,
    title: r.title ?? def.title,
    caption: r.caption ?? def.caption,
    checks: r.checks ?? [],
    evidence: r.evidence ?? "",
    tone: r.tone ?? "neutral",
    audit_seq: decisionRec?.seq ?? null,
    at: Date.now(),
    records: produced.records,
    alerts: produced.alerts,
  };
  run.events.push(ev);
  run.next += 1;
  run.done = run.next >= a.steps.length;
  save(run, dir, a.summary);
  return { event: ev, done: run.done, run_id: run.id };
}

export function labRuns() {
  if (!existsSync(labDir())) return [];
  return readdirSync(labDir())
    .filter((d) => RUN_ID.test(d) && existsSync(join(labDir(), d, "run.json")))
    .map((d) => JSON.parse(readFileSync(join(labDir(), d, "run.json"), "utf8"))           )
    .sort((x, y) => y.started_at - x.started_at)
    .slice(0, 20)
    .map((r) => ({ id: r.id, attack: r.attack, name: r.name, started_at: r.started_at, steps: r.events.length, total: r.total, done: r.done, outcome: r.events.at(-1)?.tone ?? "neutral", events: r.events }));
}
